ygen.com"],"reviewNotes":{"basis":"Official repository metadata, README, license text, and referenced installation documentation. The upstream application was not installed or executed.","installation":"README lists macOS, Windows, and Linux desktop downloads and an npm CLI with init, preview and render commands. The desktop/CLI product workflow is the scope, not a promise that all hosted services are free.","license":"Recognized SPDX metadata and the standard license text were inspected; third-party components may retain separate notices.","maintainedRepository":{"archived":false,"fork":false,"isTemplate":false,"pushedAt":"2026-11-02T10:21:19Z"},"evidence":{"readmePath":"README.md","readmeSha":"e76e22f63cd7b6f5ffce43d522781bbf30efdf6c","licensePath":"LICENSE","licenseSha":"ae06b37e1c5116ccfaa615ac25ec1aabf5658d8c"},"baselineMatches":[]},"legacyUrls":[],"identityKeys":["url:hyperframes.heygen.com","repo:heygen-com/hyperframes","github-id:1177402105"],"normalizedUrl":"hyperframes.heygen.com","repoKey":"github.com/heygen-com/hyperframes","iconUrl":"https://www.google.com/s2/favicons?domain=hyperframes.heygen.com&sz=64","tagRecords":[{"name":"video-rendering","slug":"video-rendering"},{"name":"motion-graphics","slug":"motion-graphics"},{"name":"html-video","slug":"html-video"},{"name":"cli","slug":"cli"}]},{"name":"Tangent","slug":"tangent","categorySlug":"writing-notes","tagline":"Write linked Markdown notes with a visual navigation history","description":"Tangent is a local Markdown note-writing and knowledge-management application. Link notes with wiki links, follow connected navigation maps, use sliding panels and focus modes, and search note collections with its query language. The Apache-2.0 desktop application has Windows, macOS, and Linux build targets and downloadable binaries, including a Flathub package.","platforms":["Mac","Windows","Linux"],"tags":["markdown","notes","knowledge-management","local-first"],"useCases":["Write and connect a local collection of Markdown notes","Explore linked notes through navigation maps and sliding panels","Search a research notebook with its query language"],"url":"https://www.tangentnotes.com/","github":"https://github.com/suchnsuch/tangent","repositoryId":"518874712","licenseSpdxId":"Apache-2.0","reviewedAt":"2026-11-02","pricing":"OPEN_SOURCE","isOpenSource":true,"githubStars":583,"githubStarsObservedAt":"2026-11-02T10:21:18.300Z","pushedAt":"2026-10-29T11:47:42Z","defaultBranch":"main","sources":["https://github.com/suchnsuch/Tangent","https://github.com/suchnsuch/Tangent/blob/main/README.md","https://github.com/suchnsuch/Tangent/blob/main/LICENSE.txt","https://github.com/suchnsuch/Tangent/blob/main/apps/tangent-electron/package.json","https://www.tangentnotes.com/"],"reviewNotes":{"basis":"Official GitHub metadata, README, license text and referenced installation/release documentation were reviewed. Upstream applications were not installed or executed.","installation":"README links download and Flathub pages; tangent-electron package.json explicitly includes macOS/Windows/Linux packaging targets.","license":"Official Apache-2.0 license text and repository documentation were inspected; bundled components retain their own notices.","maintainedRepository":{"archived":false,"fork":false,"isTemplate":false,"pushedAt":"2026-10-29T11:47:42Z"},"evidence":{"readmePath":"README.md","readmeSha":"65ea0cedc7495d555e33f86c55416da1294f9522","licensePath":"LICENSE.txt","licenseSha":"f49a4e16e68b128803cc2dcea614603632b04eac"},"baselineMatches":[]},"legacyUrls":[],"identityKeys":["url:tangentnotes.com","repo:suchnsuch/tangent","github-id:518874712"],"normalizedUrl":"tangentnotes.com","repoKey":"github.com/suchnsuch/tangent","iconUrl":"https://www.google.com/s2/favicons?domain=www.tangentnotes.com&sz=64","tagRecords":[{"name":"markdown","slug":"markdown"},{"name":"notes","slug":"notes"},{"name":"knowledge-management","slug":"knowledge-management"},{"name":"local-first","slug":"local-first"}]},{"name":"TreeSheets","slug":"treesheets","categorySlug":"writing-notes","tagline":"Organize notes and plans in nested spreadsheet-style grids","description":"TreeSheets combines nested grids with text and images to organize notes, plans, and structured information. Its hierarchical layout can serve as an outliner, compact mind map, or planning sheet without requiring a conventional relational database. The Zlib-licensed desktop application provides Windows, macOS, and Linux binaries and keeps documents in local files.","platforms":["Mac","Windows","Linux"],"tags":["outliner","notes","mind-mapping","desktop"],"useCases":["Outline research notes in a nested grid","Plan projects and requirements with hierarchical cells","Arrange tasks and ideas in a compact visual document"],"url":"https://strlen.com/treesheets/","github":"https://github.com/aardappel/treesheets","repositoryId":"10671623","licenseSpdxId":"Zlib","reviewedAt":"2026-11-02","pricing":"OPEN_SOURCE","isOpenSource":true,"githubStars":3187,"githubStarsObservedAt":"2026-11-02T10:21:18.300Z","pushedAt":"2026-11-01T18:59:12Z","defaultBranch":"master","sources":["https://github.com/aardappel/treesheets","https://github.com/aardappel/treesheets/blob/master/README.md","https://github.com/aardappel/treesheets/blob/master/ZLIB_LICENSE.txt","https://strlen.com/treesheets/"],"reviewNotes":{"basis":"Official GitHub metadata, README, license text and referenced installation/release documentation were reviewed. Upstream applications were not installed or executed.","installation":"README links Windows/macOS/Linux release binaries and Linux packages; ZLIB_LICENSE.txt reviewed.","license":"Official Zlib license text and repository documentation were inspected; bundled components retain their own notices.","maintainedRepository":{"archived":false,"fork":false,"isTemplate":false,"pushedAt":"2026-11-01T18:59:12Z"},"evidence":{"readmePath":"README.md","readmeSha":"3d687a62351d39bff0962a7d524529429cc62f99","licensePath":"ZLIB_LICENSE.txt","licenseSha":"2f9fa7088afad8c426106baa901c752157ec197c"},"baselineMatches":[]},"legacyUrls":[],"identityKeys":["url:strlen.com/treesheets","repo:aardappel/treesheets","github-id:10671623"],"normalizedUrl":"strlen.com/treesheets","repoKey":"github.com/aardappel/treesheets","iconUrl":"https://www.google.com/s2/favicons?domain=strlen.com&sz=64","tagRecords":[{"name":"outliner","slug":"outliner"},{"name":"notes","slug":"notes"},{"name":"mind-mapping","slug":"mind-mapping"},{"name":"desktop","slug":"desktop"}]},{"name":"zk","slug":"zk","categorySlug":"writing-notes","tagline":"Manage a plain-text Zettelkasten from the command line","description":"zk helps maintain a Markdown-based personal wiki or Zettelkasten from the terminal. Create notes from templates, filter by tags and links, and integrate the notebook with an existing editor through LSP or editor plugins. The GPL-3.0 tool supports macOS, Linux, and Windows builds. It manages notes while leaving editing and web publishing to other applications.","platforms":["Mac","Windows","Linux"],"tags":["markdown","zettelkasten","cli","notes"],"useCases":["Create linked notes from reusable templates","Find notes by tags, links, or mentions","Connect a plain-text notebook to an existing editor"],"url":"https://zk-org.github.io/zk/","github":"https://github.com/zk-org/zk","repositoryId":"323932509","licenseSpdxId":"GPL-3.0","reviewedAt":"2026-11-02","pricing":"OPEN_SOURCE","isOpenSource":true,"githubStars":2865,"githubStarsObservedAt":"2026-11-02T10:21:18.300Z","pushedAt":"2026-10-31T19:10:41Z","defaultBranch":"main","sources":["https://github.com/zk-org/zk","https://github.com/zk-org/zk/blob/main/README.md","https://github.com/zk-org/zk/blob/main/LICENSE","https://zk-org.github.io/zk/"],"reviewNotes":{"basis":"Official GitHub metadata, README, license text and referenced installation/release documentation were reviewed. Upstream applications were not installed or executed.","installation":"README documents release binaries, Homebrew, Nix, Linux packages and source builds; it notes unsigned Windows binaries and recommends a source build in that case.","license":"Official GPL-3.0 license text and repository documentation were inspected; bundled components retain their own notices.","maintainedRepository":{"archived":false,"fork":false,"isTemplate":false,"pushedAt":"2026-10-31T19:10:41Z"},"evidence":{"readmePath":"README.md","readmeSha":"475dd6ff08b9c7478c9a66f44fd524da27305f67","licensePath":"LICENSE","licenseSha":"f288702d2fa16d3cdf0035b15a9fcbc552cd88e7"},"baselineMatches":[]},"legacyUrls":[],"identityKeys":["url:zk-org.github.io/zk","repo:zk-org/zk","github-id:323932509"],"normalizedUrl":"zk-org.github.io/zk","repoKey":"github.com/zk-org/zk","iconUrl":"https://www.google.com/s2/favicons?domain=zk-org.github.io&sz=64","tagRecords":[{"name":"markdown","slug":"markdown"},{"name":"zettelkasten","slug":"zettelkasten"},{"name":"cli","slug":"cli"},{"name":"notes","slug":"notes"}]}]'::jsonb) LOOP
    SELECT id INTO category_id FROM "Category" WHERE slug = candidate->>'categorySlug';
    IF category_id IS NULL THEN RAISE EXCEPTION 'Required reviewed category is missing'; END IF;
    incoming_keys := ARRAY(SELECT jsonb_array_elements_text(candidate->'identityKeys'));
    legacy_urls := ARRAY(SELECT jsonb_array_elements_text(candidate->'legacyUrls'));
    SELECT array_agg(DISTINCT t.id) INTO matching_ids FROM "Tool" t
    WHERE t.id IN (SELECT "toolId" FROM "ToolIdentity" WHERE key = ANY(incoming_keys))
      OR t.url = ANY(legacy_urls)
      OR lower(regexp_replace(regexp_replace(regexp_replace(t.github, '^https?://(www\.)?', '', 'i'), '[?#].*$', ''), '(\.git)?/+$|\.git$', '')) = candidate->>'repoKey'
      OR lower(regexp_replace(regexp_replace(regexp_replace(t.url, '^https?://(www\.)?', '', 'i'), '[?#].*$', ''), '(\.git)?/+$|\.git$', '')) = candidate->>'repoKey'
      OR (lower(substring(t.url from '(?i)^https?://(?:www\.)?([^/?#]+)')) || rtrim(coalesce(substring(t.url from '(?i)^https?://[^/?#]+([^?#]*)'), ''), '/') || coalesce(substring(split_part(t.url, '#', 1) from '\?.*$'), '')) = candidate->>'normalizedUrl';
    IF coalesce(cardinality(matching_ids), 0) > 1 THEN
      RAISE EXCEPTION 'Identity conflict for %: multiple existing listings', candidate->>'slug';
    END IF;
    tool_id := matching_ids[1];
    IF EXISTS (SELECT 1 FROM "Tool" WHERE slug = candidate->>'slug' AND id IS DISTINCT FROM tool_id) THEN
      RAISE EXCEPTION 'Slug conflict for %: belongs to another listing', candidate->>'slug';
    END IF;

    IF tool_id IS NOT NULL THEN
      SELECT * INTO STRICT tool_row FROM "Tool" WHERE id = tool_id FOR UPDATE;
      IF EXISTS (SELECT 1 FROM "ToolIdentity" WHERE "toolId" = tool_id
          AND key LIKE 'github-id:%' AND key <> 'github-id:' || (candidate->>'repositoryId'))
        OR (tool_row.github IS NOT NULL AND lower(regexp_replace(regexp_replace(regexp_replace(tool_row.github, '^https?://(www\.)?', '', 'i'), '[?#].*$', ''), '(\.git)?/+$|\.git$', '')) <> candidate->>'repoKey'
          AND NOT EXISTS (SELECT 1 FROM "ToolIdentity" WHERE "toolId" = tool_id AND key = 'github-id:' || (candidate->>'repositoryId')))
        OR (EXISTS (SELECT 1 FROM "ToolIdentity" WHERE "toolId" = tool_id AND key LIKE 'repo:%'
            AND key <> 'repo:' || regexp_replace(candidate->>'repoKey', '^github.com/', ''))
          AND NOT EXISTS (SELECT 1 FROM "ToolIdentity" WHERE "toolId" = tool_id AND key = 'github-id:' || (candidate->>'repositoryId'))) THEN
        RAISE EXCEPTION 'Repository conflict for %: review before merging', candidate->>'slug';
      END IF;
      -- The reviewed batch does not override an earlier moderation rejection.
      IF tool_row.status IN ('REJECTED', 'APPROVED') THEN CONTINUE; END IF;
      SELECT array_agg(item ORDER BY first_position) INTO use_cases FROM (
        SELECT item, min(position) AS first_position
        FROM unnest(coalesce(tool_row."useCases", ARRAY[]::text[]) || ARRAY(SELECT jsonb_array_elements_text(candidate->'useCases')))
          WITH ORDINALITY AS items(item, position) GROUP BY item
      ) merged;
      UPDATE "Tool" SET "categoryId" = category_id,
        name = candidate->>'name', tagline = candidate->>'tagline', description = candidate->>'description',
        platforms = ARRAY(SELECT jsonb_array_elements_text(candidate->'platforms')),
        "githubStars" = (candidate->>'githubStars')::integer,
        url = CASE WHEN status = 'PENDING' AND url = ANY(legacy_urls) THEN candidate->>'url' ELSE url END,
        github = coalesce(github, candidate->>'github'), status = 'APPROVED',
        pricing = CASE WHEN status = 'PENDING' THEN (candidate->>'pricing')::"Pricing" ELSE pricing END,
        "isOpenSource" = CASE WHEN status = 'PENDING' THEN (candidate->>'isOpenSource')::boolean ELSE "isOpenSource" END,
        "useCases" = use_cases,
        source = coalesce(source, 'GITHUB_REPOSITORY'::"ToolSource"),
        "sourceUrl" = CASE WHEN source IS NULL THEN candidate->>'github' ELSE "sourceUrl" END,
        "updatedAt" = now()
      WHERE id = tool_id AND (
        "categoryId" IS DISTINCT FROM category_id OR github IS NULL OR status <> 'APPROVED'
        OR "useCases" IS DISTINCT FROM use_cases OR source IS NULL
      );
    ELSE
      tool_id := gen_random_uuid()::text;
      INSERT INTO "Tool" (id, name, slug, tagline, description, url, "iconUrl", "categoryId", github,
        pricing, "isOpenSource", platforms, status, source, "sourceUrl", "useCases", "githubStars", "updatedAt")
      VALUES (tool_id, candidate->>'name', candidate->>'slug', candidate->>'tagline', candidate->>'description',
        candidate->>'url', candidate->>'iconUrl', category_id, candidate->>'github',
        (candidate->>'pricing')::"Pricing", (candidate->>'isOpenSource')::boolean,
        ARRAY(SELECT jsonb_array_elements_text(coalesce(candidate->'platforms', '[]'::jsonb))),
        'APPROVED', 'GITHUB_REPOSITORY', candidate->>'github',
        ARRAY(SELECT jsonb_array_elements_text(candidate->'useCases')), (candidate->>'githubStars')::integer, now());
    END IF;

    INSERT INTO "ToolIdentity" (key, "toolId") SELECT unnest(incoming_keys), tool_id
      ON CONFLICT (key) DO NOTHING;
    IF EXISTS (SELECT 1 FROM "ToolIdentity" WHERE key = ANY(incoming_keys) AND "toolId" <> tool_id) THEN
      RAISE EXCEPTION 'Identity claim conflict for %', candidate->>'slug';
    END IF;
    FOR tag IN SELECT value FROM jsonb_array_elements(candidate->'tagRecords') LOOP
      INSERT INTO "Tag" (id, name, slug)
        SELECT gen_random_uuid()::text, tag->>'name', tag->>'slug'
        WHERE NOT EXISTS (SELECT 1 FROM "Tag" WHERE slug = tag->>'slug' OR lower(name) = lower(tag->>'name'));
      INSERT INTO "ToolTag" ("toolId", "tagId")
        SELECT tool_id, id FROM "Tag" WHERE slug = tag->>'slug' OR lower(name) = lower(tag->>'name')
        ORDER BY (slug = tag->>'slug') DESC LIMIT 1 ON CONFLICT DO NOTHING;
    END LOOP;
    INSERT INTO "ToolDiscovery" (id, "toolId", source, method, "sourceKey", "sourceUrl", metadata)
      VALUES (gen_random_uuid()::text, tool_id, 'GITHUB_REPOSITORY', 'editorial-review',
        'github-reviewed-2026-11-02-batch2:' || (candidate->>'repoKey'), candidate->>'github',
        jsonb_build_object('reviewedAt', candidate->>'reviewedAt', 'reviewBasis', 'official public documentation',
          'sources', candidate->'sources', 'repositoryId', candidate->>'repositoryId',
          'licenseSpdxId', candidate->>'licenseSpdxId', 'legacyUrls', candidate->'legacyUrls', 'category', candidate->>'categorySlug',
          'githubStars', candidate->'githubStars', 'observedOn', candidate->>'reviewedAt',
          'defaultBranch', candidate->>'defaultBranch', 'pushedAt', candidate->>'pushedAt',
          'reviewNotes', candidate->'reviewNotes', 'batch', 'github-reviewed-2026-11-02-batch2'))
      ON CONFLICT ("toolId", source, method, "sourceKey") DO UPDATE SET
        "sourceUrl" = EXCLUDED."sourceUrl", metadata = EXCLUDED.metadata, "lastSeenAt" = now();
  END LOOP;

END
$toools_curation$;
COMMIT;
